using CampusPlacementManagement.Data;
using CampusPlacementManagement.DTOs.Students;
using CampusPlacementManagement.Models;
using CampusPlacementManagement.Models.Enums;
using CampusPlacementManagement.Repositories.Interfaces;
using CampusPlacementManagement.Services.Interfaces;
using ClosedXML.Excel;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
namespace CampusPlacementManagement.Services;
public class StudentService:IStudentService
{
 private readonly IStudentRepository _repo;private readonly IPlacementOfficerRepository _officers;private readonly UserManager<ApplicationUser> _users;private readonly ApplicationDbContext _db;
 public StudentService(IStudentRepository repo,IPlacementOfficerRepository officers,UserManager<ApplicationUser> users,ApplicationDbContext db){_repo=repo;_officers=officers;_users=users;_db=db;}
 public async Task<Student> EnrollAsync(StudentEnrollmentDto dto,string officerUserId){var officer=await _officers.GetByUserIdAsync(officerUserId)??throw new UnauthorizedAccessException("Officer profile not found.");if(officer.Status!=AccountStatus.Approved||officer.College.Status!=CollegeStatus.Approved)throw new UnauthorizedAccessException("Officer or college is not active.");return await CreateStudentAsync(dto,officer);}
 private async Task<Student> CreateStudentAsync(StudentEnrollmentDto dto,PlacementOfficer officer){if(await _repo.RegisterNumberExistsAsync(officer.CollegeId,dto.RegisterNumber))throw new InvalidOperationException("Register number already exists in this college.");if(await _users.FindByEmailAsync(dto.Email)!=null)throw new InvalidOperationException("Email already exists.");var tempPassword="Temp@"+Guid.NewGuid().ToString("N")[..10];var u=new ApplicationUser{UserName=dto.Email,Email=dto.Email,EmailConfirmed=true,PhoneNumber=dto.MobileNumber,FullName=dto.FullName,AccountStatus=AccountStatus.Pending};var r=await _users.CreateAsync(u,tempPassword);if(!r.Succeeded)throw new InvalidOperationException(string.Join("; ",r.Errors.Select(x=>x.Description)));var s=new Student{UserId=u.Id,CollegeId=officer.CollegeId,PlacementOfficerId=officer.PlacementOfficerId,RegisterNumber=dto.RegisterNumber,Department=dto.Department,Degree=dto.Degree,GraduationYear=dto.GraduationYear,CGPA=dto.CGPA,ActiveBacklogs=dto.ActiveBacklogs,ResumeUrl=dto.ResumeUrl,Status=AccountStatus.Pending};await _repo.AddAsync(s);await _repo.SaveChangesAsync();return s;}
 public async Task<BulkImportResultDto> BulkEnrollAsync(Stream file,string fileName,string officerUserId){if(!fileName.EndsWith(".xlsx",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Only .xlsx Excel files are supported.");var officer=await _officers.GetByUserIdAsync(officerUserId)??throw new UnauthorizedAccessException("Officer profile not found.");var result=new BulkImportResultDto();using var workbook=new XLWorkbook(file);var sheet=workbook.Worksheets.First();var last=sheet.LastRowUsed()?.RowNumber()??1;result.TotalRows=Math.Max(0,last-1);for(int row=2;row<=last;row++){try{var dto=new StudentEnrollmentDto{FullName=sheet.Cell(row,1).GetString().Trim(),Email=sheet.Cell(row,2).GetString().Trim(),MobileNumber=sheet.Cell(row,3).GetString().Trim(),RegisterNumber=sheet.Cell(row,4).GetString().Trim(),Department=sheet.Cell(row,5).GetString().Trim(),Degree=sheet.Cell(row,6).GetString().Trim(),GraduationYear=sheet.Cell(row,7).GetValue<int>(),CGPA=sheet.Cell(row,8).GetValue<decimal>(),ActiveBacklogs=sheet.Cell(row,9).GetValue<int>(),ResumeUrl=sheet.Cell(row,10).GetString().Trim()};await CreateStudentAsync(dto,officer);result.SuccessfulRows++;}catch(Exception ex){result.FailedRows++;result.Errors.Add($"Row {row}: {ex.Message}");}}return result;}
 public async Task<List<Student>> GetAllAsync(string userId,string? department,int? graduationYear,string? search){var officer=await _officers.GetByUserIdAsync(userId);return await _repo.GetAllAsync(officer?.CollegeId,department,graduationYear,search);}
 public async Task<List<Student>> GetPendingAsync(string userId){var officer=await _officers.GetByUserIdAsync(userId)??throw new UnauthorizedAccessException();return await _repo.GetPendingAsync(officer.CollegeId);}
 public async Task<Student> GetByIdAsync(int id)=>await _repo.GetByIdAsync(id)??throw new KeyNotFoundException("Student not found.");
 public async Task<Student> GetMeAsync(string userId)=>await _repo.GetByUserIdAsync(userId)??throw new KeyNotFoundException("Student profile not found.");
 public async Task ApproveAsync(int id,string officerUserId){var s=await GetByIdAsync(id);var o=await _officers.GetByUserIdAsync(officerUserId)??throw new UnauthorizedAccessException();if(s.CollegeId!=o.CollegeId)throw new UnauthorizedAccessException("Student belongs to another college.");s.Status=AccountStatus.Approved;s.ApprovedAt=DateTime.UtcNow;s.User.AccountStatus=AccountStatus.Approved;await _users.AddToRoleAsync(s.User,"Student");_repo.Update(s);await _repo.SaveChangesAsync();}
 public async Task RejectAsync(int id,string officerUserId){var s=await GetByIdAsync(id);var o=await _officers.GetByUserIdAsync(officerUserId)??throw new UnauthorizedAccessException();if(s.CollegeId!=o.CollegeId)throw new UnauthorizedAccessException();s.Status=AccountStatus.Rejected;s.User.AccountStatus=AccountStatus.Rejected;_repo.Update(s);await _repo.SaveChangesAsync();}
 public async Task SuspendAsync(int id,string userId){var s=await GetByIdAsync(id);var officer=await _officers.GetByUserIdAsync(userId);if(officer!=null&&s.CollegeId!=officer.CollegeId)throw new UnauthorizedAccessException();s.Status=AccountStatus.Suspended;s.User.AccountStatus=AccountStatus.Suspended;_repo.Update(s);await _repo.SaveChangesAsync();}
 public async Task UpdateAsync(int id,StudentEnrollmentDto dto,string userId){var s=await GetByIdAsync(id);var officer=await _officers.GetByUserIdAsync(userId);if(officer!=null&&s.CollegeId!=officer.CollegeId)throw new UnauthorizedAccessException();s.User.FullName=dto.FullName;s.User.PhoneNumber=dto.MobileNumber;s.Department=dto.Department;s.Degree=dto.Degree;s.GraduationYear=dto.GraduationYear;s.CGPA=dto.CGPA;s.ActiveBacklogs=dto.ActiveBacklogs;s.ResumeUrl=dto.ResumeUrl;s.User.UpdatedAt=DateTime.UtcNow;_repo.Update(s);await _repo.SaveChangesAsync();}
}
